/* Hidden attribute override guarantee */
[hidden] {
  display: none !important;
}

:root {
  --color-bg: #181425;
  --color-card: #262b44;
  --color-accent: #3a4466;
  --color-gold: #fee761;
  --color-white: #ffffff;
  --color-red: #ff0044;
  --color-green: #38b764;
  --color-border: #000000;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  background-color: var(--color-bg);
  color: var(--color-white);
  font-family: 'Courier New', Courier, monospace, monospace;
  font-size: 16px;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
}

.app-container {
  width: 100%;
  max-width: 480px;
  display: flex;
  justify-content: center;
}

.pixel-card {
  background-color: var(--color-card);
  width: 100%;
  border: 4px solid var(--color-border);
  box-shadow:
    inset -4px -4px 0px 0px #181425,
    inset 4px 4px 0px 0px #3a4466,
    8px 8px 0px 0px rgba(0, 0, 0, 0.7);
  padding: 24px;
  display: flex;
  flex-direction: column;
  gap: 20px;
}

.card-header {
  text-align: center;
  border-bottom: 4px dashed var(--color-accent);
  padding-bottom: 12px;
}

.title {
  font-size: 24px;
  color: var(--color-gold);
  letter-spacing: 2px;
  text-transform: uppercase;
  text-shadow: 2px 2px 0px var(--color-border);
}

.subtitle {
  font-size: 14px;
  color: #8b9bb4;
  margin-top: 4px;
  text-transform: uppercase;
}

.timer-display-box {
  background-color: #0f111a;
  border: 4px solid var(--color-border);
  box-shadow: inset 2px 2px 0px 0px #000000;
  padding: 20px 10px;
  text-align: center;
}

.timer-digits {
  font-size: 48px;
  font-weight: bold;
  letter-spacing: 4px;
  color: var(--color-gold);
  text-shadow: 3px 3px 0px #000000;
  display: inline-block;
}

.speaker-roster-box {
  background-color: #1f2438;
  border: 2px solid var(--color-border);
  padding: 14px;
}

.roster-title {
  font-size: 14px;
  letter-spacing: 1px;
  color: #8b9bb4;
  margin-bottom: 10px;
}

.roster-list {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.roster-item {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 8px 12px;
  background-color: var(--color-accent);
  border: 2px solid var(--color-border);
  font-size: 16px;
  font-weight: bold;
  letter-spacing: 1px;
}

.roster-item.active {
  background-color: var(--color-gold);
  color: var(--color-border);
  box-shadow: inset -2px -2px 0px 0px #c2b036;
  position: relative;
}

.roster-item.active .status-indicator::before {
  content: "▶ ";
  font-size: 14px;
}

.roster-item.done {
  background-color: #12141f;
  color: #636b80;
  text-decoration: line-through;
}

.completion-banner {
  background-color: var(--color-green);
  border: 4px solid var(--color-border);
  box-shadow: inset -2px -2px 0px 0px #248243;
  padding: 14px;
  text-align: center;
}

.completion-text {
  font-size: 20px;
  font-weight: bold;
  color: #000000;
  letter-spacing: 2px;
  text-transform: uppercase;
}

.controls-group {
  display: flex;
  gap: 12px;
  justify-content: center;
}

.pixel-btn {
  flex: 1;
  font-family: inherit;
  font-size: 16px;
  font-weight: bold;
  letter-spacing: 1px;
  padding: 14px;
  background-color: var(--color-gold);
  color: var(--color-border);
  border: 3px solid var(--color-border);
  cursor: pointer;
  box-shadow:
    inset 2px 2px 0px 0px #ffffff,
    inset -2px -2px 0px 0px #bca82f,
    4px 4px 0px 0px var(--color-border);
  outline: none;
  transition: transform 0.05s ease;
}

.pixel-btn:hover {
  background-color: #ffef8a;
}

.pixel-btn:focus-visible {
  outline: 3px solid #ffffff;
  outline-offset: 2px;
}

.pixel-btn:active {
  transform: translate(2px, 2px);
  box-shadow:
    inset 1px 1px 0px 0px #ffffff,
    inset -1px -1px 0px 0px #bca82f,
    2px 2px 0px 0px var(--color-border);
}

.btn-secondary {
  background-color: #8b9bb4;
  color: #000000;
  box-shadow:
    inset 2px 2px 0px 0px #c0cbdc,
    inset -2px -2px 0px 0px #5a6988,
    4px 4px 0px 0px var(--color-border);
}

.btn-secondary:hover {
  background-color: #a3b2cb;
}

.btn-secondary:active {
  transform: translate(2px, 2px);
  box-shadow:
    inset 1px 1px 0px 0px #c0cbdc,
    inset -1px -1px 0px 0px #5a6988,
    2px 2px 0px 0px var(--color-border);
}

.pixel-btn:disabled {
  opacity: 0.5;
  cursor: not-allowed;
  box-shadow: none;
  transform: none;
}

@media (max-width: 400px) {
  .pixel-card {
    padding: 16px;
  }
  .timer-digits {
    font-size: 38px;
  }
  .title {
    font-size: 20px;
  }
  .pixel-btn {
    font-size: 14px;
    padding: 10px;
  }
}

document.addEventListener('DOMContentLoaded', () => {
  const PARTICIPANTS = ['Alice', 'Bob', 'Charlie', 'Dana'];
  const SPEAKER_DURATION_SECONDS = 90;

  let currentIndex = 0;
  let remainingSeconds = SPEAKER_DURATION_SECONDS;
  let timerInterval = null;
  let isComplete = false;

  const timerDisplay = document.getElementById('timer-display');
  const rosterList = document.getElementById('roster-list');
  const completionMessage = document.getElementById('completion-message');
  const nextBtn = document.getElementById('next-btn');
  const resetBtn = document.getElementById('reset-btn');

  function formatTime(seconds) {
    const mins = Math.floor(seconds / 60);
    const secs = seconds % 60;
    return `${mins}:${secs < 10 ? '0' : ''}${secs}`;
  }

  function renderRoster() {
    rosterList.innerHTML = '';
    PARTICIPANTS.forEach((name, index) => {
      const li = document.createElement('li');
      li.className = 'roster-item';

      if (!isComplete && index === currentIndex) {
        li.classList.add('active');
        li.setAttribute('aria-current', 'true');
      } else if (index < currentIndex || isComplete) {
        li.classList.add('done');
      }

      const nameSpan = document.createElement('span');
      nameSpan.className = 'status-indicator';
      nameSpan.textContent = name;

      const badgeSpan = document.createElement('span');
      badgeSpan.className = 'badge';
      if (!isComplete && index === currentIndex) {
        badgeSpan.textContent = 'SPEAKING';
      } else if (index < currentIndex || isComplete) {
        badgeSpan.textContent = 'DONE';
      } else {
        badgeSpan.textContent = 'WAITING';
      }

      li.appendChild(nameSpan);
      li.appendChild(badgeSpan);
      rosterList.appendChild(li);
    });
  }

  function updateUI() {
    timerDisplay.textContent = formatTime(remainingSeconds);
    renderRoster();

    if (isComplete) {
      completionMessage.removeAttribute('hidden');
      nextBtn.disabled = true;
    } else {
      completionMessage.setAttribute('hidden', '');
      nextBtn.disabled = false;
    }
  }

  function advanceToNext() {
    if (isComplete) return;

    currentIndex++;
    if (currentIndex >= PARTICIPANTS.length) {
      finishStandup();
    } else {
      remainingSeconds = SPEAKER_DURATION_SECONDS;
      updateUI();
    }
  }

  function finishStandup() {
    clearInterval(timerInterval);
    timerInterval = null;
    isComplete = true;
    remainingSeconds = 0;
    updateUI();
  }

  function tick() {
    if (remainingSeconds > 0) {
      remainingSeconds--;
      timerDisplay.textContent = formatTime(remainingSeconds);
    } else {
      advanceToNext();
    }
  }

  function startTimer() {
    if (timerInterval) {
      clearInterval(timerInterval);
    }
    timerInterval = setInterval(tick, 1000);
  }

  function resetStandup() {
    clearInterval(timerInterval);
    timerInterval = null;
    currentIndex = 0;
    remainingSeconds = SPEAKER_DURATION_SECONDS;
    isComplete = false;
    updateUI();
    startTimer();
  }

  nextBtn.addEventListener('click', () => {
    advanceToNext();
  });

  resetBtn.addEventListener('click', () => {
    resetStandup();
  });

  // Keyboard accessibility shortcuts
  document.addEventListener('keydown', (e) => {
    if (e.code === 'Space' && e.target === document.body) {
      e.preventDefault();
      if (!isComplete) {
        advanceToNext();
      }
    }
  });

  // Initial boot
  updateUI();
  startTimer();
});
